//! Genuine same-QueryDb raw issuer controls, distinct from finite DATA fixtures.
use super::*;
#[path="../../../../analyze/fixtures/native-api/fixture.rs"]mod initial;
fn api_root(case:&str)->PathBuf{let root=crate::test_scratch::dir(&format!("actual-api-{case}"));for(relative,bytes)in initial::files(case).unwrap(){let path=root.join(relative);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,bytes).unwrap();}root}
#[test]fn actual_api_complete_three_phase_source_exceeds_fixture_limit_and_uses_no_body_or_source_reopen(){
 let root=api_root("global_fields");for index in 0..130{std::fs::write(root.join(format!("code/padding-{index:04}.dm")),b"// actual original CODE file without API sites\n").unwrap();}let physical=Physical{reads:Mutex::new(BTreeMap::new()),fail_policy:Mutex::new(None)};let inputs=RecordingInputs::new(&physical,5_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let configuration=root.join("tools/ci/lint_scopes.toml");let capture=workspace_capture::capture(&front,&inputs,discover(&root,&inputs),&configuration).unwrap();let current=snapshot(&front,&db,&inputs,&capture);let before=physical.reads();let bodies=db.db().stats(dm_query::Kind(4)).computed;
 let record=|data:&dq_analyze::captured_api_pages::ApiData|serde_json::json!({"sites":data.sites(),"source_text":data.source_text(),"allow_used":data.allow_used()});let cold=current.with_native_api(&current.tree,|data,_,_|{assert!(data.sites().iter().any(|site|site.rule=="field_write"&&site.rel=="code/fields.dm"));assert!(data.sites().iter().any(|site|site.rule=="field_write"&&site.rel=="code/unit_tests/raw.dm"));assert!(!data.sites().iter().any(|site|site.rule=="vars_helpers"&&site.rel=="code/unit_tests/raw.dm"));Ok(record(data))}).unwrap();let warm=current.with_native_api(&current.tree,|data,_,_|Ok(record(data))).unwrap();assert_eq!(cold,warm);assert_eq!(physical.reads(),before);assert_eq!(db.db().stats(dm_query::Kind(4)).computed,bodies);
 let foreign=crate::query_db::QueryDb::default();let called=std::cell::Cell::new(false);assert!(foreign.with_workspace_api(&capture,&current.workspace_native_read().unwrap(),|_,_,_|{called.set(true);Ok(())}).is_err());assert!(!called.get());
 let partial_inputs=RecordingInputs::new(FileSystemInputs,5_000_000_000);let partial_front=frontend(&root,&partial_inputs,&db);let partial=Arc::new(workspace_discovery::discover(&partial_inputs,DiscoveryContract{root:root.clone(),recursive_roots:vec![root.join("code/unit_tests")]}).unwrap());let partial=workspace_capture::capture(&partial_front,&partial_inputs,partial,&configuration).unwrap();let partial=snapshot(&partial_front,&db,&partial_inputs,&partial);assert!(partial.with_native_api(&partial.tree,|_,_,_|{called.set(true);Ok(())}).is_err());assert!(!called.get());
 println!("NATIVE_API_FULL={cold}");
}
#[test]fn actual_api_source_io_quota_consumer_1450_cancel_unwind_and_retry_preserve_actual_error(){
 let root=api_root("allow_phase_order");let physical=Physical{reads:Mutex::new(BTreeMap::new()),fail_policy:Mutex::new(Some(root.join("code/both.dm")))};let inputs=RecordingInputs::new(&physical,5_000_000_000);let db=Arc::new(crate::query_db::QueryDb::default());let front=frontend(&root,&inputs,&db);let configuration=root.join("tools/ci/lint_scopes.toml");let failure=workspace_capture::capture(&front,&inputs,discover(&root,&inputs),&configuration).err().unwrap();assert_eq!(failure.raw_os_error(),Some(1450));*physical.fail_policy.lock().unwrap()=None;
 let capture=workspace_capture::capture(&front,&inputs,discover(&root,&inputs),&configuration).unwrap();let current=snapshot(&front,&db,&inputs,&capture);let before=physical.reads();let called=std::cell::Cell::new(false);let error=db.with_workspace_api_limit(&capture,&current.workspace_native_read().unwrap(),1,|_,_,_|{called.set(true);Ok(())}).err().unwrap();assert!(matches!(error,dq_analyze::captured_reactive_reads::Failure::Operational(ref error)if error.kind()==io::ErrorKind::OutOfMemory));assert!(!called.get());
 let cancel=crate::daemon::control::Cancellation::default();let binding=crate::daemon::control::bind_with_deadline(cancel.clone(),std::time::Instant::now()+std::time::Duration::from_secs(60));let first=current.with_native_api(&current.tree,|_,_,_|{cancel.cancel();Err::<(),_>(io::Error::from_raw_os_error(1450))}).err().unwrap();assert!(matches!(first,dq_analyze::captured_reactive_reads::Failure::Operational(ref error)if error.raw_os_error()==Some(1450)));drop(binding);assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(||current.with_native_api(&current.tree,|_,_,_|->io::Result<()>{panic!("actual API consumer unwind")}))).is_err());current.with_native_api(&current.tree,|data,_,_|{assert!(!data.sites().is_empty());assert!(!data.allow_used().is_empty());Ok(())}).unwrap();assert_eq!(physical.reads(),before);
}
